import json
import itertools

def solve_puzzle():
    # Define puzzle attributes and values
    houses = [1, 2]  # left to right as seen from across the street
    attributes = {
        "Name": ["Eric", "Arnold"],
        "birthday month": ["sept", "april"],
        "favorite color": ["yellow", "red"],
    }

    # Helper to evaluate constraints on a candidate assignment
    def satisfies_constraints(assignment):
        # assignment: dict with keys "Name", "birthday month", "favorite color"
        # each maps house -> value

        # Clue 1: Eric is the person who loves yellow.
        for h in houses:
            if assignment["Name"][h] == "Eric" and assignment["favorite color"][h] != "yellow":
                return False
            if assignment["favorite color"][h] == "yellow" and assignment["Name"][h] != "Eric":
                return False

        # Clue 2: The person whose birthday is in April is in the first house.
        if assignment["birthday month"][1] != "april":
            return False

        # Clue 3: The person who loves yellow is not in the first house.
        if assignment["favorite color"][1] == "yellow":
            return False

        return True

    # Generate all bijective assignments for each attribute across houses
    names_perms = itertools.permutations(attributes["Name"])
    months_perms = itertools.permutations(attributes["birthday month"])
    colors_perms = itertools.permutations(attributes["favorite color"])

    # Convert permutations to mappings from house -> value
    solutions = []
    for name_tuple in names_perms:
        name_map = {houses[i]: name_tuple[i] for i in range(len(houses))}
        for month_tuple in months_perms:
            month_map = {houses[i]: month_tuple[i] for i in range(len(houses))}
            # Quick pruning: apply Clue 2 early
            if month_map[1] != "april":
                continue
            for color_tuple in colors_perms:
                color_map = {houses[i]: color_tuple[i] for i in range(len(houses))}
                # Quick pruning: apply Clue 3 early
                if color_map[1] == "yellow":
                    continue

                assign = {
                    "Name": name_map,
                    "birthday month": month_map,
                    "favorite color": color_map,
                }

                if satisfies_constraints(assign):
                    solutions.append(assign)

    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # In case multiple solutions exist, we still pick the first; puzzle is expected to be unique.
        pass

    sol = solutions[0]

    # Build JSON output
    header = ["House", "Name", "birthday month", "favorite color"]
    rows = []
    for h in sorted(houses):
        rows.append([str(h), sol["Name"][h], sol["birthday month"][h], sol["favorite color"][h]])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
